      client.close(closeReason);
      throw renderError;
    },
  });

  const completion = client.select('query');
  const session = sessions[0];

  await nextImmediate();

  const value = { value: 1 };
  session.reader.push({ done: false, value });

  assert.deepStrictEqual(await completion, {
    query: 'query',
    status: 'cancelled',
