  });
  await nextImmediate();

  assert.deepStrictEqual(rendered, [{ query: 'query', value }]);
  assert.equal(session.signal.aborted, true);
  assert.strictEqual(session.signal.reason, closeReason);
  assert.equal(session.reader.cancelReasons.length, 1);
  assert.strictEqual(session.reader.cancelReasons[0], closeReason);
  assert.equal(session.reader.releaseCalls, 1);

  assertClosed(() => client.select('later'));

  session.reader.push({ done: true, value: 'late' });
  await nextImmediate();

  assert.equal(session.reader.releaseCalls, 1);
});
